def _migrate_status_history_locked(self) -> None:
    """为缺历史的旧同步状态补一条兼容项（audit 字段为 None）。

    仅在加载时补齐内存结构；持久化留给首次后续写（见 _save_locked
    的惰性落盘），避免只读查询改动状态文件。同时按既有历史校正
    全局 cursor 计数。
    """
    changed = False
    for tenant_id, bucket in self._tenants.items():
        bucket.setdefault("credential_status_history", {})
        history_map = bucket["credential_status_history"]
        for issuer_did, issuer_sync in (
            bucket.get("credential_status_sync", {}) or {}
        ).items():
            issuer_history = history_map.setdefault(issuer_did, {})
            for credential_id, row in issuer_sync.items():
                entries = issuer_history.setdefault(credential_id, [])
                if not entries:
                    entries.append(
                        {
                            "cursor": None,
                            "status": row.get("status"),
                            "reason": row.get("reason"),
                            "updated_at": row.get("updated_at"),
                            "issuer_key_version": int(
                                row.get("issuer_key_version", 1)
                            ),
                            "audit_seq": None,
                            "audit_timestamp": None,
                            "compat": True,
                        }
                    )
                    changed = True
        # 校正全局 cursor：取所有历史条目 cursor 的最大值
        for issuer_history in history_map.values():
            for entries in issuer_history.values():
                for entry in entries:
                    cursor = entry.get("cursor")
                    if isinstance(cursor, int) and cursor > self._status_history_seq:
                        self._status_history_seq = cursor
    return None  # noqa: PLR1711 （changed 仅供调试，不触发主动落盘）

